    otPlatUartReceived(buf, (uint16_t)size);

    while (otTaskletsArePending(instance))
    {
        otTaskletsProcess(instance);
    }

exit:

    if (buf != NULL)
    {
        free(buf);
    }

    if (instance != NULL)
    {
        otInstanceFinalize(instance);
    }

    return 0;
}
